<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Bouncing Ball Physics</title>
    <style>
        body { background: #121212; color: white; font-family: sans-serif; display: flex; justify-content: center; align-items: center; min-height: 100vh; margin: 0; }
        .container { text-align: center; width: 640px; max-width: 95%; padding: 20px; box-sizing: border-box; display: flex; flex-direction: column; align-items: center;}

        canvas#sim { 
            border: 2px solid #333; 
            background-color: #1e1e1e; 
            box-shadow: 0 4px 15px rgba(0,0,0,0.6); 
            display: block;
            width: 600px !important; /* Ensure CSS pixel dimensions match intrinsic for physics consistency */
            height: 600px !important;
            cursor: crosshair; 
        }

        .controls { margin-top: 15px; display: flex; gap: 8px;}

        button { padding: 8px 16px; background: #333; color: white; border: none; border-radius: 4px; cursor: pointer; font-size: 0.9rem; transition: all 0.2s ease; }
        button:hover { background: #555; transform: translateY(-1px); }

        button#play.playing-state { 
            background-color: green !important; 
            color: white; 
        }
    </style>
</head>
<body>

<div class="container">
    <canvas id="sim" width="600" height="600"></canvas>

    <div class="controls">
        <button id="drop">Drop Ball</button>
        <button id="play">Play / Pause</button>
        <button id="clear">Clear All</button>
    </div>
</div>

<script>
// Physics Playground Logic

// Wait for DOM to load implicitly (script is at end of body)
const canvas = document.getElementById('sim');
const ctx = canvas.getContext('2d', { alpha: false }); // Optimized opaque context

// Configuration Constants (Physics Parameters)
const W = canvas.width;   // Canvas width in pixels (600)
const H = canvas.height;  // Canvas height in pixels (600)
const GRAVITY = 0.4;       // Gravity acceleration per step unit (dt=1)
const RESTITUTION = 0.75;  // Energy retained after bounce (<1 for loss, <bounciness>)
const FRICTION = 0.98;     // Horizontal friction coefficient

// Simulation State Variables
let isPlaying = false;
let animationFrameId = null;
let balls = [];

// --- API Implementation: window.sim ---

window.sim = {
    w: W,
    h: H,

    // Returns a snapshot of the ball data (array of objects)
    balls: () => balls.map(b => ({ x: b.x, y: b.y, vx: b.vx, vy: b.vy, r: b.r })),

    addBall(x = W / 2, y = H / 2, vx = 0, vy = 0, r = 15) {
        // Ensure ball starts within canvas bounds to avoid tunneling immediately upon creation.
        let safeX = x;
        let safeY = y;

        if (safeX < r) safeX = r;
        if (safeY < r) safeY = r;
        if (safeX > W - r) safeX = W - r;
        if (safeY > H - r) safeY = H - r;

        balls.push({ x: safeX, y: safeY, vx: vx, vy: vy, r: r });
    },

    clear() {
        balls = [];
    },

    step(dt = 1) {
        // Physics Update Loop

        for (const b of balls) {
            // Apply Gravity to vertical velocity component
            b.vy += GRAVITY * dt;

            // Apply Friction/Damping to horizontal movement
            if(Math.abs(b.vx) > 0.1) {
                b.vx *= FRICTION;
            } else {
                b.vx = 0; 
            }

            // Update Position based on Velocity (scaled by time step dt)
            b.x += b.vx * dt;
            b.y += b.vy * dt;

            // --- Boundary Collisions & Clamping ---

            // Floor Collision (Bottom Edge)
            if (b.y > H - b.r) {
                b.y = H - b.r;          // Clamp position to edge
                b.vy *= -RESTITUTION;   // Reverse velocity with energy loss

                // Stop micro-bouncing when near rest on floor for stability
                if (Math.abs(b.vy) < GRAVITY * 0.5) {
                    b.vy = 0;
                }
            }

            // Ceiling Collision (Top Edge)
            if (b.y < b.r) {
                b.y = b.r;              // Clamp position to edge
                b.vy *= -RESTITUTION;   // Reverse velocity with energy loss
            }

            // Left Wall Collision
            if (b.x < b.r) {
                b.x = b.r;
                b.vx *= -RESTITUTION;   // Reverse horizontal component
            }

            // Right Wall Collision
            if (b.x > W - b.r) {
                b.x = W - b.r;
                b.vx *= -RESTITUTION;   // Reverse horizontal component
            }
        }

        this.draw();
    },

    draw() {
        ctx.clearRect(0, 0, W, H);

        for (const b of balls) {
            ctx.beginPath();
            ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
            // White fills contrast well on dark theme canvas background (#1e1e1e)
            ctx.fillStyle = '#ffffff'; 
            ctx.fill();
        }
    }
};

// --- UI & Event Handlers ---

function togglePlay() {
    const btn = document.getElementById('play');
    isPlaying = !isPlaying;

    if (isPlaying) {
        // Continuous animation loop using requestAnimationFrame
        function loop() {
            if (!isPlaying) return; // Check flag inside to prevent extra call on untoggle
            window.sim.step(1);       // Advance simulation by one step unit

            animationFrameId = requestAnimationFrame(loop);
        }
        loop();

        btn.textContent = "Pause";
        btn.classList.add('playing-state');
    } else {
        cancelAnimationFrame(animationFrameId);
        btn.textContent = "Play / Pause";
        btn.classList.remove('playing-state');
    }
}

// Button: Drop Ball (Programmatic drop)
document.getElementById('drop').addEventListener('click', () => {
    window.sim.addBall(); 
});

// Button: Clear All Balls
document.getElementById('clear').addEventListener('click', () => {
    window.sim.clear();
});

// Button: Play / Pause Toggle
const playBtn = document.getElementById('play');
playBtn.addEventListener('click', togglePlay);

// Canvas Interaction: Click to add ball at cursor position
canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();

    // Calculate scaling factor in case CSS display size differs from buffer resolution.
    // Though we set them equal, this ensures robustness if styles change or window resizes with fixed pixels.
    const scaleX = W / rect.width;
    const scaleY = H / rect.height;

    const x = (e.clientX - rect.left) * scaleX;
    const y = (e.clientY - rect.top) * scaleY;

    window.sim.addBall(x, y);
});
</script>

</body>
</html>
